/* Trap glue shared by all C-level round-trip fixtures.
 *
 * crt0.S invokes init_mtvec() as a constructor; trap.S's m_trap_entry
 * tail-calls handle_trap on every exception or interrupt. vplat_syscalls.c
 * routes syscalls through direct MMIO (UART + SimControl/HTIF), not
 * through `ecall`, so there's no syscall-dispatch table here. Any trap
 * is treated as a fatal error: print a diagnostic and exit.
 */

#ifdef __cplusplus
extern "C"
{
#endif

#include <stdint.h>
#include <stdio.h>

#define WRITE_ERROR(format, ...) \
  fprintf(stderr, "\033[31m[ERROR] " format "\033[0m\n", ##__VA_ARGS__)

__attribute__((used, noreturn)) void _exit(int exit_status);

void exception_handler(void)
{
  /* XLEN-wide so rv64 mepc/mtval are not truncated and the format is warning-
   * free on both ABIs (unsigned long is 32-bit on ilp32, 64-bit on lp64). */
  unsigned long mcause, mdcause, mepc, mtval;

  asm volatile("csrr %0, mcause" : "=r"(mcause));
  asm volatile("csrr %0, mdcause" : "=r"(mdcause));
  asm volatile("csrr %0, mepc" : "=r"(mepc));
  asm volatile("csrr %0, mtval" : "=r"(mtval));

  const unsigned long intbit = 1UL << (__riscv_xlen - 1);  /* mcause MSB */

  WRITE_ERROR("Trap occurred!");
  WRITE_ERROR("mcause: 0x%lx", mcause);
  WRITE_ERROR("mdcause: 0x%lx", mdcause);
  WRITE_ERROR("mepc: 0x%lx", mepc);
  WRITE_ERROR("mtval: 0x%lx", mtval);

  if ((mcause & intbit) == 0) {
    WRITE_ERROR("Exception code: %lu", mcause);
  } else {
    WRITE_ERROR("Interrupt occurred! Cause: %lu", mcause & ~intbit);
  }

  _exit((int) mcause);
}

void handle_trap(unsigned long cause, void* tf)
{
  (void) cause;
  (void) tf;
  exception_handler();
}

extern void m_trap_entry(void);

__attribute__((constructor)) void init_mtvec(void)
{
  uintptr_t handler_address = (uintptr_t) &m_trap_entry;
  asm volatile("csrw mtvec, %0" : : "r"(handler_address));
}

#ifdef __cplusplus
}
#endif

// Presentation filter for a cycle-accurate engine's raw output.
//
// `run --mode cycle` runs vsim standalone, which is chatty: it prints a startup
// banner (Copyright / Version) on stdout -- interleaved with the program's own
// stdout -- and verbose `[info]` log lines on stderr, including the headline
// "<N> cycles simulated" count. The user wants only the program's output and
// that count (restated as andesim's own one-line result), with vsim's banner
// and log hidden.
//
// VsimFilter classifies each output line, in arrival order, into drop / stdout /
// stderr, and lifts the cycle count out of the otherwise-hidden log so the
// driver can re-print it under its own [andesim] prefix. The logic is pure (no
// I/O); the spawn/relay loop that feeds it lives in process.cpp.
#ifndef ANDESIM_VSIM_FILTER_HPP
#define ANDESIM_VSIM_FILTER_HPP

#include <cstdint>
#include <optional>
#include <string>
#include <string_view>

namespace andes_sim {

// Lift the count from vsim's "<N> cycles simulated" log line, e.g.
// "[info] 3573 cycles simulated" -> 3573. Returns nullopt for any other line.
// Matches on the "<digits> cycles simulated" shape, tolerant of the leading
// "[info]" tag and surrounding spaces, so it never mistakes the neighbouring
// "[info] 0.354s elapsed, ...Hz" timing line for a count.
std::optional<uint64_t> parse_cycles_line(std::string_view line);

// Decides how each line of a cycle-accurate engine's output is presented.
// Feed lines in arrival order with their source stream (1 = stdout, 2 = stderr),
// excluding the trailing newline:
//   - vsim's startup banner (Copyright / Version, plus its trailing blank line)
//     is dropped,
//   - every `[info]` log line is dropped,
//   - the "<N> cycles simulated" line is dropped but its count is lifted into
//     cycles() for the driver to re-print, and
//   - everything else passes through -- the program's own stdout, and any real
//     diagnostic vsim logs above info level ([warn]/[error]/...) on stderr.
// Stateful: it tracks when the banner has ended (the first real stdout line), so
// a "Version :" the program itself prints later is NOT mistaken for the banner.
class VsimFilter {
 public:
  enum class Dest { kDrop, kStdout, kStderr };

  Dest classify(int stream, std::string_view line);

  // The lifted "N cycles simulated" count, once a matching line has been seen.
  std::optional<uint64_t> cycles() const { return cycles_; }

 private:
  std::optional<uint64_t> cycles_;
  bool seen_program_output_ = false;  // stdout: false until the banner ends
};

// Strip vsim's startup banner from a captured stdout buffer, returning what
// remains (the program's own output). The buffer-mode counterpart to VsimFilter
// for the hybrid relay: the vsim leg's stdout was captured whole (its [info] log
// already dropped at capture), so only the banner needs removing -- the same
// Copyright / Version / leading-blank rule, applied line by line. A final line
// without a trailing newline is preserved without one.
std::string strip_vsim_banner(std::string_view buf);

}  // namespace andes_sim

#endif  // ANDESIM_VSIM_FILTER_HPP
